mapper.sql:
WHERE customers.is_active = 1

    AND (
    address LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customer_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND DATE(customers.created) >= #{filter.dateFrom}


    AND DATE(customers.created) <= #{filter.dateTo}


    AND customers.customer_code = #{filter.code}


    AND customers.customer_code = #{filter.other}


    AND customers.province_id = #{filter.provinceId}


    AND customers.district_id = #{filter.districtId}


    AND customers.village_id = #{filter.villageId}


    AND customers.commune_id = #{filter.communeId}


    AND customers.id = #{filter.organizationId}


    AND customers.id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND customers.created_by = #{filter.createdBy}

mapper.select:
SELECT customers.id AS id, customers.customer_code AS code, customers.name AS name, customers.address AS address, COALESCE(customers.main_number, customers.mobile_number, customers.other_number) AS telephone, customers.email AS email FROM customers LEFT JOIN customer_cgroups ON customers.id = customer_cgroups.customer_id
GROUP BY customers.id ORDER BY customers.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
